      const parsedRetries = parseIntOption(opts.retries, {
        min: 0,
        max: Number.MAX_SAFE_INTEGER,
        name: "Retries",
      });
      if (!parsedRetries.ok) {
        error(`Invalid --retries value: ${parsedRetries.error}`, {
          suggestion: "Example: --retries 5",
