        // AC: @cli-agent-commands ac-12 — stream text to stdout in interactive mode
        // AC: @cli-agent-commands ac-11 — suppress streaming in --json mode
        let didStream = false;
        const onUpdate = isJsonMode()
          ? undefined
          : (update: SessionUpdate) => {
