        // AC: @cli-agent-commands ac-7 - CLI overrides agent defaults
        let timeoutOverride: number | undefined;
        if (opts.timeout) {
          const parsed = parseIntOption(opts.timeout, { min: 1, max: 10080, name: "Timeout" });
          if (!parsed.ok) {
